public class JSearchArrayValues {
	//Paso 1: Definir el metodo
	public static void searchArrays(double[] lst1, double[] lst2) {
		//Paso 1.1: Iterar por los valores en el segundo arreglo
		for (double val2 : lst2) {
			//Paso 1.1.1: Imprimir el valor del segundo arreglo si existe en el primer arreglo
			for (double val1 : lst1) {
				if (val1 == val2) {
					System.out.println(val2 + " existe en ambos arreglos.");   
				}
			}
		}
	}
	public static void main(String[] args) {
		double[] values1 = {2.0, 11, 4, 5, 3, 3.5, 4, 10, 16, 3};
		double[] values2 =  {7, 11, 3, 1.0};
		searchArrays(values1, values2);
	}
}

